@@ -852,3 +852,247 @@ it("observes genuine installed finite start-now opaque minimum refusal", async (
   if (failures.length)
     throw new AggregateError(failures, "installed opaque changefeed observation or cleanup failed");
 }, 60000);
+
+it("observes installed current changefeed minimum admission and retained replay", async () => {
+  const { recordRawSse } = await import("@bdp/server/testing");
+  const { stringifyJsonValue } = await import("@bdp/protocol");
+  type Page = {
+    after: string; observedHeadPosition: string; next: string | null;
+    groups: { checkpoint: string; changes: { resource: { id: string } }[] }[];
+  };
+  const controller = new AbortController(), streamController = new AbortController();
+  const directory = mkdtempSync(path.join(tmpdir(), "bdp-current-feed-installed-"));
+  const ownedDirectory = realpathSync(directory), token = randomBytes(32).toString("base64url");
+  const failures: unknown[] = [], failureCategories: string[] = [];
+  function fail(category: string, error: unknown) {
+    if (!failures.includes(error)) { failures.push(error); failureCategories.push(category); }
+  }
+  let deadlineFired = false;
+  const workTimer = setTimeout(() => {
+    deadlineFired = true; const error = new Error("installed current feed work deadline");
+    fail("work-deadline", error); controller.abort(error);
+  }, 45000);
+  let child: Awaited<ReturnType<typeof launchInstalledTransaction>> | undefined;
+  let binding: ReturnType<typeof installedTransactionBinding> | undefined;
+  let recorder: ReturnType<typeof recordRawSse> | undefined, childDrain: Promise<void> | undefined;
+  let attempted = 0, settledFiniteExchanges = 0, launchAttempted = false, cleanClose = false,
+    pendingDrained = false, streamDrained = false, directoryRemoved = false, stopUnknown = false,
+    lateCleanupRejectionObserved = false, assertionsCompleted = false;
+  const processEvents: {
+    exit: { code: number | null; signal: NodeJS.Signals | null } | undefined;
+    close: { code: number | null; signal: NodeJS.Signals | null } | undefined;
+  } = { exit: undefined, close: undefined };
+  const pending = new Set<Promise<unknown>>();
+  const responses: { ordinal: number; method: string; url: string; status: number;
+    bodyOctets: number; bodySha256: string; wireSha256: string;
+    requestHeaders: { name: string; value: string }[]; headers: Record<string, string | null> }[] = [];
+  let stream: Record<string, unknown> | null = null;
+  const safeHeaders = [...retainedHeaders, "etag"];
+  function dispatch() {
+    controller.signal.throwIfAborted();
+    if (attempted >= 10) throw new Error("installed current feed global dispatch bound");
+    return ++attempted;
+  }
+  async function bounded<T>(operation: Promise<T>, deadline: number, label: string) {
+    let timer: ReturnType<typeof setTimeout> | undefined;
+    try {
+      return await Promise.race([operation, new Promise<never>((_, reject) => {
+        timer = setTimeout(() => reject(new Error(label)), Math.max(1, deadline - performance.now()));
+      })]);
+    } finally { if (timer !== undefined) clearTimeout(timer); }
+  }
+  function track<T>(operation: Promise<T>) {
+    pending.add(operation);
+    void operation.then(() => { pending.delete(operation); settledFiniteExchanges++; },
+      () => { pending.delete(operation); settledFiniteExchanges++; });
+    return operation;
+  }
+  try {
+    launchAttempted = true;
+    const launching = launchInstalledTransaction(entry, { scope, directory, create: true, artifacts,
+      credentials: [{ token, principal: "writer", canMutate: true }] }, controller.signal);
+    void launching.catch((error: unknown) => fail("launch", error));
+    child = await launching;
+    const ownedProcess = child.child;
+    ownedProcess.once("exit", (code, signal) => { processEvents.exit = { code, signal }; });
+    childDrain = new Promise<void>((resolve) => {
+      ownedProcess.once("close", (code, signal) => { processEvents.close = { code, signal }; resolve(); });
+    });
+    expect(ownedProcess.exitCode).toBeNull(); expect(ownedProcess.signalCode).toBeNull();
+    expect(child.ready).toMatchObject({ scope, profile: "transactional", history: false, claimEligible: false });
+    binding = installedTransactionBinding(child.ready, sourceCommit, fixture);
+    const address = new URL(child.ready.listenUrl as string);
+    const routes = [
+      { method: "POST" as const, url: scope + "operations/batch" },
+      { method: "GET" as const, url: scope + "changes/?after=genesis" },
+      { method: "GET" as const, url: scope + "changes/?start=now" },
+    ];
+    function executor() {
+      return createRawHttpExchangeExecutor(
+        { transport: "plain", host: address.hostname, port: Number(address.port) },
+        { requestTimeoutMs: 5000, maximumBodyBytes: 131072,
+          exactMode: { scope, profile: "transactional", routes: [...routes],
+            maximumRequestHeaderBytes: 16384, maximumRequestBodyBytes: 65536,
+            defaultCredentialRef: "writer", credentialHandles: [{ id: "writer", headerNames: ["authorization"] }],
+            resolveCredentials: () => ({ authorization: "Bearer " + token }) } });
+    }
+    let execute = executor();
+    async function exchange(method: "POST" | "GET", url: string, expected: number,
+      headerLines: { name: string; value: string }[], input?: unknown) {
+      if (!routes.some((r) => r.method === method && r.url === url))
+        throw new Error("unbound installed current feed target");
+      const ordinal = dispatch();
+      const response = await track(execute({ method, url, signal: controller.signal,
+        credentialRef: "writer", raw: { headerLines,
+          ...(input === undefined ? {} : { bodyBytes: Buffer.from(JSON.stringify(input)) }) } }));
+      expect(response.exactRequest?.writeState).toBe("complete");
+      expect(response.exactRequest?.headerLines.find((h) => h.name.toLowerCase() === "host")?.value).toBe("reference.invalid");
+      expect(response.url).toBe(url);
+      if (!response.wireResponseBytes?.length || response.bodyOctets === undefined)
+        throw new Error("missing installed current feed actual wire/body");
+      expect(response.bodyOctets).toBe(Buffer.byteLength(response.bodyText));
+      expect(response.headers["x-bdp-development"]).toBe("non-attesting");
+      responses.push({ ordinal, method, url, status: response.status, bodyOctets: response.bodyOctets,
+        bodySha256: digest(response.bodyText), wireSha256: digest(response.wireResponseBytes),
+        requestHeaders: headerLines.map((h) => ({ ...h })),
+        headers: Object.fromEntries(safeHeaders.map((name) => [name, response.headers[name] ?? null])) });
+      expect(response.status).toBe(expected);
+      const value: unknown = JSON.parse(response.bodyText);
+      return { response, value };
+    }
+    let secondReceipt: Record<string, unknown> | undefined;
+    for (const id of ["a", "b"]) {
+      const seed = await exchange("POST", scope + "operations/batch", 200,
+        [{ name: "content-type", value: "application/json" }, { name: "accept", value: "application/json" },
+          { name: "idempotency-key", value: "current-feed-" + id }],
+        { operations: [{ operation: "createBead", id: "beads/" + id, type: beadType,
+          properties: { title: "current-feed-" + id } }] });
+      expect(validReceipt(seed.value), JSON.stringify(validReceipt.errors)).toBe(true);
+      expect(seed.value).toMatchObject({ status: "completed", requiredPosition: id === "a" ? "pos-1" : "pos-2" });
+      secondReceipt = seed.value as Record<string, unknown>;
+    }
+    if (!secondReceipt) throw new Error("missing second installed receipt");
+    const current = [secondReceipt.scopeEpoch, secondReceipt.authorizationView, "pos-2"];
+    const k = [
+      { name: "bdp-scope-epoch", value: String(secondReceipt.scopeEpoch) },
+      { name: "bdp-authorization-view", value: String(secondReceipt.authorizationView) },
+      { name: "bdp-minimum-scope-position", value: "pos-2" },
+    ];
+    const u = k.map((h) => ({ ...h, value: h.name === "bdp-minimum-scope-position" ? "unknown" : h.value }));
+    const p = u.map((h) => ({ ...h, value: h.name === "bdp-minimum-scope-position" ? "pos-01" : h.value }));
+    const json = { name: "Accept", value: "application/json" }, sse = { name: "Accept", value: "text/event-stream" };
+    const firstResponse = await exchange("GET", scope + "changes/?after=genesis", 200, [json, ...k]);
+    expect(validPage(firstResponse.value), JSON.stringify(validPage.errors)).toBe(true);
+    const first = firstResponse.value as Page;
+    expect(first.groups).toHaveLength(1); expect(first.observedHeadPosition).toBe("pos-2");
+    const cp1 = first.groups[0]!.checkpoint;
+    expect(first.next).toBe(scope + "changes/?after=" + cp1);
+    const afterUrl = first.next!;
+    routes.push({ method: "GET", url: afterUrl }); execute = executor();
+    const secondResponse = await exchange("GET", afterUrl, 200, [json, ...k]);
+    expect(validPage(secondResponse.value), JSON.stringify(validPage.errors)).toBe(true);
+    const page2 = secondResponse.value as Page;
+    expect(page2.groups).toHaveLength(1); expect(page2.next).toBeNull(); expect(page2.after).toBe(cp1);
+    expect(page2.observedHeadPosition).toBe("pos-2");
+    for (const response of [firstResponse.response, secondResponse.response])
+      expect(contextNames.map((name) => response.headers[name])).toEqual(current);
+    expect(page2.groups[0]!.changes[0]!.resource.id).toBe(scope + "beads/b");
+    const cp2 = page2.groups[0]!.checkpoint; expect(cp2).not.toBe(cp1);
+    for (const [url, headers] of [
+      [scope + "changes/?after=genesis", [json, ...u, { name: "If-None-Match", value: "*" }]],
+      [afterUrl, [json, ...p, { name: "If-Match", value: '"missing"' }]],
+      [scope + "changes/?start=now", [sse, ...u]],
+      [scope + "changes/?start=now", [sse, ...u, { name: "Last-Event-ID", value: cp1 }]],
+      [scope + "changes/?after=genesis", [json, ...u,
+        { name: "Last-Event-ID", value: "bad" }, { name: "Last-Event-ID", value: "also-bad" }]],
+    ] as const) {
+      const result = await exchange("GET", url, 503, [...headers]);
+      expect(validProblem(result.value), JSON.stringify(validProblem.errors)).toBe(true);
+      expect(result.value).toMatchObject({ code: "catch-up-timeout", status: 503, retry: "after-delay" });
+      expect(contextNames.map((name) => result.response.headers[name])).toEqual(current);
+      expect(result.response.headers["content-type"]).toBe("application/problem+json");
+      expect(result.response.headers["cache-control"]).toBe("private, no-store");
+      expect(result.response.headers["retry-after"]).toBe("1");
+      expect(result.response.headers.etag).toBeUndefined();
+      expect(result.response.headers["x-bdp-development-limit"]).toBeUndefined();
+      expect(result.response.bodyText).not.toContain("event: change-group");
+    }
+    const ordinal = dispatch();
+    const streamHeaders: [string, string][] = [["Authorization", "Bearer " + token],
+      ...[sse, ...k, { name: "Last-Event-ID", value: cp1 }].map((h): [string, string] => [h.name, h.value])];
+    recorder = recordRawSse({ dial: child.ready.listenUrl as string, host: new URL(scope).host,
+      target: new URL(scope).pathname + "changes/?after=genesis", headers: streamHeaders,
+      signal: AbortSignal.any([controller.signal, streamController.signal]), timeoutMs: 5000 });
+    const rec = recorder;
+    await rec.ready; expect(rec.status).toBe(200);
+    await rec.until(() => rec.frames.filter((f) => f.startsWith("id: ")).length >= 1);
+    const expectedFrame = "id: " + cp2 + "\nevent: change-group\ndata: " + stringifyJsonValue(page2.groups[0]);
+    expect(rec.frames.filter((f) => f.startsWith("id: "))).toEqual([expectedFrame]);
+    expect(rec.headers["content-type"]).toBe("text/event-stream");
+    expect(contextNames.map((name) => rec.headers[name])).toEqual(current);
+    expect(controller.signal.aborted).toBe(false); expect(streamController.signal.aborted).toBe(false);
+    expect(rec.destroyed).toBe(false);
+    const liveBeforeClose = !rec.destroyed && !controller.signal.aborted && !streamController.signal.aborted;
+    await rec.close(); streamDrained = true;
+    expect(rec.frames.filter((f) => f.startsWith("id: "))).toEqual([expectedFrame]);
+    const actualGroup: unknown = JSON.parse(rec.frames.filter((f) => f.startsWith("id: "))[0]!.split("\ndata: ")[1]!);
+    expect(actualGroup).toEqual(page2.groups[0]);
+    stream = { request: ordinal, status: rec.status, readyObserved: true, liveBeforeClose, afterDrain: true,
+      frames: rec.frames, group: actualGroup, checkpoint: cp2, wireSha256: digest(rec.wireBytes),
+      bodySha256: digest(rec.body), requestHeaders: streamHeaders.filter(([name]) => name !== "Authorization"),
+      headers: Object.fromEntries(safeHeaders.map((name) => [name, rec.headers[name] ?? null])) };
+    expect(attempted).toBe(10); expect(settledFiniteExchanges).toBe(9); expect(responses).toHaveLength(9);
+    expect(responses.map((r) => r.status)).toEqual([200, 200, 200, 200, 503, 503, 503, 503, 503]);
+    assertionsCompleted = true; controller.signal.throwIfAborted();
+  } catch (error) { fail("observation", error); }
+  finally {
+    controller.abort(); streamController.abort(); clearTimeout(workTimer);
+    const cleanupDeadline = performance.now() + 10000;
+    const cleaning = (async () => {
+      const cleanupFailures: unknown[] = [];
+      try { if (recorder) { await recorder.close(); streamDrained = true; } }
+      catch (error) { cleanupFailures.push(error); }
+      const pendingResults = await Promise.allSettled([...pending]);
+      pendingDrained = pending.size === 0;
+      for (const result of pendingResults) if (result.status === "rejected") cleanupFailures.push(result.reason);
+      if (child) {
+        const closing = child.close();
+        void closing.catch((error: unknown) => {
+          lateCleanupRejectionObserved = true; fail("late-child-close", error);
+        });
+        const results = await Promise.allSettled([closing, childDrain]);
+        for (const result of results) if (result.status === "rejected") cleanupFailures.push(result.reason);
+        if (!cleanupFailures.length) {
+          expect(processEvents.exit).toEqual({ code: 0, signal: null });
+          expect(processEvents.close).toEqual({ code: 0, signal: null });
+          expect(child.child.exitCode).toBe(0);
+          if (!child.child.pid) throw new Error("missing owned child pid");
+          expect(() => process.kill(child!.child.pid!, 0)).toThrow();
+          cleanClose = true;
+        }
+      }
+      if (cleanupFailures.length) throw new AggregateError(cleanupFailures, "installed current feed cleanup failed");
+    })();
+    void cleaning.catch((error: unknown) => fail("cleanup-operation", error));
+    try {
+      await bounded(cleaning, cleanupDeadline, "installed current feed total cleanup deadline");
+      if (cleanClose && pendingDrained && (recorder === undefined || streamDrained) &&
+          realpathSync(directory) === ownedDirectory) {
+        rmSync(directory, { recursive: true, force: false }); directoryRemoved = true;
+      } else if (launchAttempted) stopUnknown = true;
+    } catch (error) { stopUnknown = true; fail("cleanup", error); }
+    console.log(JSON.stringify({ observation: "private-installed-current-changefeed-minimum",
+      outcome: failures.length ? "failed" : "passed", attempted, settledFiniteExchanges, responses, stream,
+      declaredSourceCommit: sourceCommit, workspaceDirty,
+      witnessSourceSha256: digest(readFileSync(fileURLToPath(import.meta.url))),
+      trackedDiffSha256: digest(execFileSync("git", ["diff", "--binary", "HEAD"], { cwd: root })),
+      sourceLimitation: "Declared source and witness/diff hashes; installed payload/configuration independently bound by external validation",
+      entryLiteral: entry, entry: resolvedEntry, entrySha256, binding, ready: child?.ready ?? null,
+      childPid: child?.child.pid ?? null, processEvents, cleanClose, closed: cleanClose,
+      stopUnknown, lateCleanupRejectionObserved, pendingDrained, streamDrained,
+      pendingOperationsAtReport: pending.size, directory, directoryRemoved,
+      directoryAbsent: !existsSync(directory), launchAttempted, assertionsCompleted, deadlineFired,
+      failureCategories, failureCount: failures.length, claimEligible: false }));
+  }
